async function studioFetch(url,options={}){const response=await fetch(url,{credentials:'same-origin',...options,headers:{'X-Requested-With':'XMLHttpRequest',...(options.headers||{})}});const contentType=response.headers.get('content-type')||'';if(!response.ok){const body=contentType.includes('application/json')?await response.json().catch(()=>null):await response.text().catch(()=>'');throw new Error(body?.error||body?.message||`Erreur HTTP ${response.status}`)}return contentType.includes('application/json')?response.json():response}
