async function renderActiveSlide(){motionController?.stop();const p=store.project,slide=getActiveSlide(),tpl=state.templates.find(t=>t.id===slide.templateId);const canvas=$('#studio-canvas');canvas.style.width=p.format.width+'px';canvas.style.height=p.format.height+'px';if(!tpl){canvas.replaceChildren(Object.assign(document.createElement('p'),{textContent:`Le template « ${slide.templateId} » n’a pas pu être chargé.`}));return}const node=renderSlide(p,slide,'preview',state);canvas.replaceChildren(node);if(canvas.querySelector('[data-rendered-template-id]')?.dataset.renderedTemplateId!==slide.templateId)showToast(`Le rendu ne correspond pas au template ${slide.templateId}`,'error');await waitForImages(node).catch(e=>showToast(e.message,'error'));if(!node.isConnected)return;await fitSlide(node).catch(e=>console.warn('[STUDIO] Texte non ajusté',e));if(node.isConnected){runValidation();makeCanvasElementsInteractive();motionController=startStudioMotion(node,{playing:!window.matchMedia('(prefers-reduced-motion: reduce)').matches});renderMotionControls();}}
