function setFormation(formationId){const cfg=FORMATION_CONFIG[formationId];if(!cfg){showToast(`Thème inconnu : ${formationId}`,'error');return}store.commit(`Thème changé en ${cfg.label}`,p=>{p.formation=formationId;p.themeId=cfg.defaultThemeId;const s=p.slides[p.activeSlideIndex];if(!s.content._manual||s.content._autoFormation!==formationId){s.content={...defaultContentForFormation(formationId),footer:{...s.content.footer}}}else{s.content._incompatibleFormation=s.content._autoFormation}s.content.eyebrow=formationId==='OR'?'INTÉGRALE ACADEMY':`FORMATION ${formationId}`;s.content.highlightedText=formationId==='OR'?'INTÉGRALE':formationId;const current=state.templateRegistry[s.templateId];if(current?.isSocialSuite){const next=readyTemplates().find(t=>t.isSocialSuite&&t.isCarousel===current.isCarousel&&t.isSession===current.isSession&&t.sessionKind===current.sessionKind&&t.formationPreset===formationId&&t.professionIndex===current.professionIndex);if(next){applySocialTemplate(p,next);p.themeId=cfg.defaultThemeId;return}p.slides=[s];p.activeSlideIndex=0;s.templateId='new3_prism';s.layoutVariantId=s.templateId;p.format=FORMATS.instagram_square;}if(current?.isMetier||current?.isGeneral||current?.isBts||current?.isSeasonal){const next=readyTemplates().find(t=>(t.isMetier||t.isGeneral||t.isBts)&&t.formationPreset===formationId&&t.professionIndex===current.professionIndex)||state.templateRegistry.new3_prism;s.templateId=next.id;s.layoutVariantId=next.id;normalizeSlideContentForTemplate(s,next);}},'formation-change');showToast(`Thème ${cfg.label} appliqué`,'success')}
