function iconPreview(label=''){const key=String(label).toLowerCase();if(key.includes('incendie'))return '🔥';if(key.includes('mobilité'))return '🚘';if(key.includes('calendrier'))return '📅';if(key.includes('finance'))return '€';if(key.includes('localisation'))return '📍';if(key.includes('certification')||key.includes('validation'))return '✓';if(key.includes('emploi'))return '💼';if(key.includes('documents'))return '▣';if(key.includes('progression'))return '↗';if(key.includes('alerte'))return '!';if(key.includes('direction'))return '★';if(key.includes('formation'))return '✦';return '◆'}
function renderStudioSidebarPanelEnhanced(tab){renderStudioSidebarPanel(tab);tab=normalizeStudioPanelId(tab);const panel=$(`[data-studio-panel-content="${tab}"]`);if(!panel)return;if(tab==='branding'){const th=state.themes[store.project.formation]||state.themes.OR;panel.innerHTML=`<label>Formation ou thème<select id="brandFormation">${Object.keys(state.themes).map(f=>`<option value="${f}" ${f===store.project.formation?'selected':''}>${esc(FORMATION_CONFIG[f]?.label||f)}</option>`).join('')}</select></label><p><strong>${esc(FORMATION_CONFIG[store.project.formation]?.label||store.project.formation)}</strong></p><p>${esc(th.positioning||'Identité Intégrale Academy')}</p><div class="studio-theme-swatches"><i style="background:${esc(th.primary)}"></i><i style="background:${esc(th.secondary)}"></i><i style="background:${esc(th.accent)}"></i><i style="background:${esc(th.surfaceDark)}"></i></div><label><input type="checkbox" id="gridToggle"> Quadrillage</label><p>Charte verrouillée</p>`}if(tab==='elements')panel.innerHTML=`<div class="studio-elements-library"><h3>Emojis</h3><div class="studio-emoji-grid">${EMOJI_LIBRARY.map(x=>`<button type="button" data-add-emoji="${x}" title="Ajouter ${x}">${x}</button>`).join('')}</div><h3>Pictogrammes</h3><div class="studio-pictogram-grid">${ICON_CATEGORIES.map(x=>`<button type="button" data-add-icon="${esc(x)}"><span>${iconPreview(x)}</span>${esc(x)}</button>`).join('')}</div><p>Après ajout, sélectionnez l’élément pour le déplacer, le redimensionner, le tourner ou changer son opacité.</p></div>`;if(tab==='media')panel.innerHTML=`<label class="studio-upload">Ajouter une photo ou un visuel au template<input id="visualInput" type="file" accept=".png,.svg,.webp,.jpg,.jpeg,image/png,image/svg+xml,image/webp,image/jpeg"></label><small>PNG, JPG, WebP ou SVG · 5 Mo maximum. Le visuel ajouté devient librement déplaçable et redimensionnable.</small><hr><label class="studio-upload">Remplacer le logo<input id="logoInput" type="file" accept=".png,.svg,.webp,.jpg,.jpeg,image/png,image/svg+xml,image/webp,image/jpeg"></label><div class="studio-logo-meta"><img class="studio-logo-preview" src="${store.project.branding.logoUrl}"><strong>${store.project.branding.logoName||'Logo officiel Intégrale Academy'}</strong><small>Logo actif sur toutes les slides</small><button data-action="logoOfficial">Revenir au logo officiel</button></div>`;if(tab==='ai')panel.insertAdjacentHTML('afterbegin','<p>Générez le texte ici, ou utilisez <strong>Modifier avec l’IA</strong> sous le template pour transformer son univers visuel.</p>')}

function renderTemplateContentFields(template,c){const supported=template?.supportedContent||['title','introduction','cta'];const labels={eyebrow:'Surtitre',title:'Titre',highlightedText:'Mot/sigle surligné',introduction:'Introduction',cta:'Appel à l’action',quote:'Citation',author:'Auteur',startDate:'Date de début',endDate:'Date de fin',examDate:'Date d’examen',date:'Date',location:'Lieu',availability:'Places disponibles',duration:'Durée',financing:'Financement',daysRemaining:'Jours ou places restantes',sessionNumber:'Numéro de session',before:'Avant',after:'Après',question:'Question',answer:'Réponse',explanation:'Explication'};let html=`<p><strong>${esc(template?.name||'Template')}</strong><br><small>Champs adaptés au modèle sélectionné. Les autres données restent conservées.</small></p>`;for(const k of supported){if(k==='stats'){html+=`<h3>Statistiques</h3>${statsEditor(c)}`;continue}if(k==='steps'){html+=`<h3>Étapes</h3>${listEditor('steps',c.steps||[],['title','text'])}`;continue}if(k==='modules'){html+=`<h3>Modules</h3>${listEditor('modules',c.modules||[],['title','duration'])}`;continue}if(k==='faq'){html+=`<h3>FAQ</h3>${listEditor('faq',c.faq||[],['q','a'])}`;continue}if(k==='footer'){html+=`${field('footer.website','Site',c.footer?.website)}${field('footer.phone','Téléphone',c.footer?.phone)}`;continue}html+=field(k,labels[k]||k,c[k]||'', ['title','introduction','quote','explanation'].includes(k)?'textarea':'input')}return html}
function statsEditor(c){const data=c.stats||[];return data.map((s,i)=>`${field(`stats.${i}.label`,`Libellé ${i+1}`,s.label)}${field(`stats.${i}.value`,`Valeur ${i+1}`,s.value)}`).join('')||'<p>Aucune statistique. Ajoutez-en dans les données du projet.</p>'}
function listEditor(name,items,keys){const seed=items.length?items:[{}];return seed.map((it,i)=>keys.map(k=>field(`${name}.${i}.${k}`,`${name} ${i+1} — ${k}`,it[k]||'')).join('')).join('')}

function field(k,l,v,type='input'){return `<label>${l}${type==='textarea'?`<textarea data-content="${k}">${esc(v)}</textarea>`:`<input data-content="${k}" value="${esc(v)}">`}</label>`}
function renderFilmstrip(){$('#filmstrip').innerHTML=store.project.slides.map((s,i)=>`<button class="social-studio__thumb ${i===store.project.activeSlideIndex?'is-active':''}" data-slide="${i}">${i+1}<br><small>${esc(s.content.title||s.templateId)}</small></button>`).join('')+'<button data-action="addSlide">+ Slide</button>'}
function runValidation(){const node=$('#studio-canvas .social-studio-slide');if(!node)return {blockingErrors:[],warnings:[],info:[]};const rendered=validateStudioSlide(node);const projectIssues=validateProject(store.project);renderValidationPanel(rendered,projectIssues);return rendered}function renderQuality(){runValidation()}function renderValidationPanel(v,projectIssues=[]){store.project.validation={errors:v.blockingErrors,warnings:[...v.warnings,...projectIssues]};const html='<h3>Vérification</h3><button type="button" data-action="autoFix">Corriger automatiquement</button>'+v.info.map(i=>`<div class="social-studio__ok">✓ ${esc(i.message)}</div>`).join('')+v.warnings.map(i=>`<div class="social-studio__warning">⚠ ${esc(i.message)}</div>`).join('')+projectIssues.map(i=>`<div class="social-studio__warning">⚠ ${esc(i.message)}</div>`).join('')+v.blockingErrors.map(i=>`<button class="social-studio__error" data-select-error>✕ ${esc(i.message)}</button>`).join('')+(!v.blockingErrors.length?'<p>✅ Aucun problème bloquant détecté.</p>':'');$('#qualityPanel').innerHTML=html;const check=$('[data-studio-panel-content="validation"]');if(check&&!check.hidden)check.innerHTML=html;}
function escapeSelector(value){return globalThis.CSS?.escape?CSS.escape(String(value)):String(value).replace(/["\\]/g,'\\$&')}
function selectedCanvasElement(id=store.project.ui?.selectedElementId){return id?$('#studio-canvas')?.querySelector(`[data-studio-element-id="${escapeSelector(id)}"]`):null}
function installElementResizeHandle(el){$$('.studio-element-resize').forEach(handle=>handle.remove());if(!el||el.matches('[data-logo-id],svg'))return;if(window.getComputedStyle(el).position==='static')el.style.position='relative';const handle=document.createElement('i');handle.className='studio-element-resize';handle.dataset.elementResize='true';handle.dataset.editorOnly='true';handle.title='Agrandir ou réduire cet élément';handle.setAttribute('aria-label','Agrandir ou réduire cet élément');el.append(handle)}
function normalizedElementProperty(prop,raw){const value=Number(raw);if(prop==='scale'||prop==='opacity')return value/100;return value}
function elementOutput(prop,value){if(prop==='scale'||prop==='opacity')return `${Math.round(Number(value)*100)} %`;if(prop==='rotation')return `${Math.round(Number(value))}°`;if(prop==='fontSize')return `${Math.round(Number(value))} px`;return `${Math.round(Number(value))} px`}
function renderInspector(){const id=store.project.ui?.selectedElementId,slide=getActiveSlide(),box=$('#inspectorContext'),node=selectedCanvasElement(id);if(!id||!node){box.innerHTML='<p>Sélectionnez un élément pour afficher ses propriétés.</p>';return}const override=getElementOverride(slide,id),isLogo=node.matches('[data-logo-id]'),isText=node.dataset.studioTextEditable==='true',name=node.dataset.studioElementName||'Élément',computed=window.getComputedStyle(node),scale=Number(override.scale)||1,opacity=Number.isFinite(Number(override.opacity))?Number(override.opacity):(Number.parseFloat(computed.opacity)||1),fontSize=Number(override.fontSize)||Number.parseFloat(computed.fontSize)||32,rotation=Number(override.rotation)||0,x=Number(override.x)||0,y=Number(override.y)||0,textValue=override.text!==undefined?override.text:String(node.textContent||'').trim(),contentKey=node.dataset.contentKey||'';const logo=isLogo?getSlideLogo(slide):null;box.innerHTML=`<div class="studio-element-controls"><span class="studio-element-controls__type">${isLogo?'Identité visuelle':isText?'Texte modifiable':'Bloc de mise en page'}</span><h3>${esc(name)}</h3>${isText?`<label>Texte<textarea data-element-text="true"${contentKey?` data-element-content-key="${esc(contentKey)}"`:''}>${esc(textValue)}</textarea></label>`:''}${isLogo?`<label class="studio-logo-slider"><span>Largeur du logo <output>${Math.round(logo.width)} px</output></span><input data-logo-prop="width" type="range" min="60" max="${maxLogoWidth()}" step="5" value="${logo.width}"></label><div class="studio-logo-size-actions"><button type="button" data-action="logoSmaller">− Petit</button><button type="button" data-action="logoReset">Taille idéale</button><button type="button" data-action="logoLarger">+ Grand</button></div>`:''}<div class="studio-element-controls__grid"><label><span>Position X <output>${Math.round(x)} px</output></span><input data-element-prop="x" type="number" min="-1080" max="1080" step="1" value="${x}"></label><label><span>Position Y <output>${Math.round(y)} px</output></span><input data-element-prop="y" type="number" min="-1920" max="1920" step="1" value="${y}"></label></div><label><span>Échelle <output>${Math.round(scale*100)} %</output></span><input data-element-prop="scale" type="range" min="20" max="300" step="1" value="${Math.round(scale*100)}"></label>${isText?`<label><span>Taille du texte <output>${Math.round(fontSize)} px</output></span><input data-element-prop="fontSize" type="range" min="8" max="220" step="1" value="${Math.round(fontSize)}"></label>`:''}<label><span>Rotation <output>${Math.round(rotation)}°</output></span><input data-element-prop="rotation" type="range" min="-180" max="180" step="1" value="${rotation}"></label><label><span>Opacité <output>${Math.round(opacity*100)} %</output></span><input data-element-prop="opacity" type="range" min="5" max="100" step="1" value="${Math.round(opacity*100)}"></label><div class="studio-element-controls__actions"><button type="button" data-action="elementBackward">Arrière-plan</button><button type="button" data-action="elementForward">Premier plan</button><button type="button" data-action="elementReset">Réinitialiser cet élément</button></div><p class="studio-element-help">Glissez l’élément pour le déplacer. Utilisez la poignée bleue pour changer sa taille. Double-cliquez sur un texte pour l’éditer directement.</p></div>`}
function ensureAlignmentGuides(root){if(!root||root.querySelector('.studio-alignment-overlay'))return;const overlay=document.createElement('div');overlay.className='studio-alignment-overlay';overlay.dataset.editorOnly='true';overlay.innerHTML='<div class="studio-canvas-ruler studio-canvas-ruler--top"></div><div class="studio-canvas-ruler studio-canvas-ruler--left"></div><i class="studio-alignment-guide studio-alignment-guide--x"></i><i class="studio-alignment-guide studio-alignment-guide--y"></i><span class="studio-alignment-guide__label">Centré</span>';root.append(overlay)}
function showAlignmentGuides({x=false,y=false,label='Centré'}={}){const overlay=$('#studio-canvas .studio-alignment-overlay');if(!overlay)return;overlay.classList.toggle('show-x',Boolean(x));overlay.classList.toggle('show-y',Boolean(y));const text=overlay.querySelector('.studio-alignment-guide__label');if(text)text.textContent=label;overlay.classList.toggle('is-active',Boolean(x||y))}
function hideAlignmentGuides(){showAlignmentGuides()}
function makeCanvasElementsInteractive(){const root=$('#studio-canvas .social-studio-slide');if(!root)return;ensureAlignmentGuides(root);const selected=selectedCanvasElement();if(selected){selected.classList.add('studio-selected');installElementResizeHandle(selected)}}
function selectElement(el){if(!el?.dataset?.studioElementId)return;store.project.ui=store.project.ui||{};store.project.ui.selectedElementId=el.dataset.studioElementId;$$('.studio-selected').forEach(x=>x.classList.remove('studio-selected'));el.classList.add('studio-selected');installElementResizeHandle(el);renderInspector()}
function startInlineTextEdit(el){if(!el||el.dataset.studioTextEditable!=='true')return;selectElement(el);const handle=el.querySelector(':scope > [data-editor-only]');handle?.remove();editing={el,old:el.textContent};el.contentEditable='plaintext-only';el.focus();document.execCommand?.('selectAll',false,null)}
function commitInlineTextEdit(el){if(!editing)return;const key=el.dataset.contentKey,value=el.textContent.trim(),id=el.dataset.studioElementId;editing=null;el.removeAttribute('contenteditable');if(key)setContentValue(key,value,'Texte modifié');else store.commit('Texte modifié',p=>setElementOverride(p.slides[p.activeSlideIndex],id,{text:value}),'element-change');showToast('Texte modifié','success')}
function cancelInlineTextEdit(){if(!editing)return;const el=editing.el;el.textContent=editing.old;el.removeAttribute('contenteditable');editing=null;installElementResizeHandle(el);showToast('Modification annulée','info')}
function getContentValue(path){return path.split('.').reduce((o,k)=>o?.[k],getActiveSlide().content)??''}
function setContentValue(path,value,label='Contenu modifié'){store.commit(label,p=>{const active=p.slides[p.activeSlideIndex],content=active.content,field=path.replace(/^data\./,'');if(getActiveTemplate().isCarousel&&PUBLICATION_DATA_FIELDS.some(([key])=>key===field)){for(const other of p.slides)if(other!==active&&other.templateId===active.templateId)other.content._publicationFields=(other.content._publicationFields||[]).filter(key=>key!==field);}content._publicationFields=[...new Set([...(content._publicationFields||[]),path.replace(/^data\./,'')])];const parts=path.replace(/^data\./,'').split('.');let o=p.slides[p.activeSlideIndex].content;while(parts.length>1){const k=parts.shift();o[k]=o[k]||{};o=o[k]}o[parts[0]]=value;o._manual=true})}
async function saveStudioProject(){if(cfg.demo){store.dirty=false;return {demo:true}}if(store.project.ui?.isSaving)return;store.project.ui.isSaving=true;try{const j=await studioFetch('/api/admin/social-visuals',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({post:store.project})});store.project.id=j.post.id;store.dirty=false;return j}catch(e){console.error('[STUDIO] Échec de sauvegarde',e);showToast(`Enregistrement impossible : ${e.message}`,'error');throw e}finally{store.project.ui.isSaving=false}}
async function importLogo(file){const fd=new FormData();fd.append('file',file);fd.append('type','logo');const j=await studioFetch('/api/admin/studio/media',{method:'POST',body:fd});store.commit('Logo ajouté',p=>{p.branding.logoUrl=j.media.url;p.branding.logoName=file.name;p.branding.logoVisible=true});showToast('Logo importé','success')}
async function importVisual(file){const fd=new FormData();fd.append('file',file);fd.append('type','visual');const j=await studioFetch('/api/admin/studio/media',{method:'POST',body:fd});store.commit('Visuel ajouté',p=>{const slide=p.slides[p.activeSlideIndex],count=(slide.elements||[]).length;slide.elements=slide.elements||[];slide.elements.push({id:crypto.randomUUID(),type:'image',url:j.media.url,label:file.name,x:120+(count%4)*36,y:170+(count%5)*34,width:260})},'media-add');showToast('Photo ou visuel ajouté au template','success')}
function renderAiDesignStatus(){const status=$('#aiDesignStatus'),design=getActiveSlide().options?.aiArtDirection;if(!status)return;status.textContent=design?`Direction artistique active : ${design.label||design.id||'personnalisée'}. Les éléments ajoutés restent modifiables.`:''}
async function applyAiDesignPrompt(){const input=$('#aiDesignPrompt'),prompt=String(input?.value||'').trim(),status=$('#aiDesignStatus');if(!prompt){showToast('Décrivez d’abord la transformation souhaitée.','info');input?.focus();return}if(status)status.textContent='L’IA prépare une nouvelle direction artistique…';try{const response=await studioFetch('/api/admin/studio/ai-transform',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt,formation:store.project.formation,templateId:getActiveSlide().templateId})});const design=response.design||response;store.commit(`Direction artistique IA : ${design.label||'personnalisée'}`,p=>{const slide=p.slides[p.activeSlideIndex],width=Number(p.format?.width)||1080,height=Number(p.format?.height)||1080,positions=[[.08,.28],[.84,.3],[.12,.66],[.8,.64],[.47,.23],[.5,.72]];slide.options=slide.options||{};slide.options.aiArtDirection=design;slide.elements=(slide.elements||[]).filter(element=>element.source!=='ai-transform');for(const [index,glyph] of (design.decorations||[]).slice(0,6).entries()){const [left,top]=positions[index]||[.12+index*.12,.25+index*.08],fontSize=index===0?82:64;slide.elements.push({id:crypto.randomUUID(),type:'emoji',glyph,label:`Décoration ${design.label||'IA'}`,source:'ai-transform',x:Math.round(Math.min(width-fontSize-24,Math.max(24,width*left))),y:Math.round(Math.min(height-fontSize-24,Math.max(24,height*top))),fontSize})}},'ai-design');if(status)status.textContent=`Transformation appliquée : ${design.label||'direction artistique personnalisée'}.`;showToast('Le template a été transformé avec l’IA','success')}catch(error){if(status)status.textContent='La transformation n’a pas pu être appliquée.';showToast(`IA impossible : ${error.message}`,'error')}}
function resetAiDesign(){store.commit('Direction artistique IA réinitialisée',p=>{const slide=p.slides[p.activeSlideIndex];if(slide.options)delete slide.options.aiArtDirection;slide.elements=(slide.elements||[]).filter(element=>element.source!=='ai-transform')},'ai-design');showToast('Direction artistique d’origine restaurée','success')}
async function previewFacebookCover(){
 let dialog=$('#facebookProfileDialog');
 if(!dialog){dialog=document.createElement('dialog');dialog.id='facebookProfileDialog';dialog.className='facebook-profile-dialog';dialog.setAttribute('aria-label','Aperçu Facebook mobile');dialog.innerHTML='<form method="dialog"><button>Fermer</button></form><h2>Aperçu Facebook mobile</h2><div data-facebook-preview></div><p>Simulation avec le recadrage centré, la photo de profil et la note Facebook. À l’import, conservez le cadrage sans zoom supplémentaire.</p>';document.body.append(dialog)}
 const target=$('[data-facebook-preview]',dialog);target.textContent='Préparation de votre couverture…';if(!dialog.open)dialog.showModal();
 try{const project=structuredClone(store.project),slide=project.slides[project.activeSlideIndex];const data=await exporter.exportSlide({project,slide,outputWidth:project.format.width,outputHeight:project.format.height,onStatus:message=>target.textContent=message});target.replaceChildren(renderFacebookProfilePreview(data))}catch(error){target.textContent='Aperçu impossible : '+error.message}
}
async function doExport(scale=1){if(store.project.ui?.isExporting)return;store.project.ui.isExporting=true;const buttons=$$('[data-action="exportStandard"],[data-action="exportHd"],[data-action="exportMotion"],[data-action="exportCarousel"]'),outputWidth=store.project.format.width*scale,outputHeight=store.project.format.height*scale;try{buttons.forEach(button=>button.disabled=true);$('#exportMessage').textContent='Préparation…';const data=await exporter.exportSlide({project:store.project,slide:getActiveSlide(),outputWidth,outputHeight,type:'png',onStatus:m=>$('#exportMessage').textContent=m});const a=document.createElement('a');a.href=data;a.download=($('#exportFilename').value||'studio-visuel')+(scale===2?'-hd':'')+'.png';a.click();$('#exportMessage').textContent=`Export terminé : ${outputWidth} × ${outputHeight}`;showToast('Export terminé','success')}catch(e){console.error('[STUDIO] Export impossible',e);$('#exportMessage').textContent=`Export impossible : ${e.message}`;showToast(`Erreur pendant l’export : ${e.message}`,'error')}finally{buttons.forEach(button=>button.disabled=false);store.project.ui.isExporting=false}}

function getSlideLogo(slide=getActiveSlide()){slide.logo=slide.logo||{...DEFAULT_LOGO_SETTINGS};clampLogo(slide.logo);return slide.logo}
function maxLogoWidth(){return ({linkedin_cover:250,facebook_cover:240})[store.project.format.id]||320}
function clampLogo(logo){logo.width=Math.max(60,Math.min(maxLogoWidth(),Number(logo.width)||DEFAULT_LOGO_SETTINGS.width));logo.opacity=Math.max(.2,Math.min(1,Number.isFinite(Number(logo.opacity))?Number(logo.opacity):DEFAULT_LOGO_SETTINGS.opacity));return logo}
function updateLogoPreview(logo){const node=$('#studio-canvas [data-logo-id]');if(node){node.style.setProperty('--studio-logo-size',`${logo.width}px`);node.style.opacity=logo.opacity}const sizeOutput=$('[data-logo-prop="width"]')?.closest('label')?.querySelector('output');const opacityOutput=$('[data-logo-prop="opacity"]')?.closest('label')?.querySelector('output');if(sizeOutput)sizeOutput.textContent=`${Math.round(logo.width)} px`;if(opacityOutput)opacityOutput.textContent=`${Math.round(logo.opacity*100)} %`}
function changeLogoSize(delta,label='Taille du logo modifiée'){store.commit(label,p=>{const logo=getSlideLogo(p.slides[p.activeSlideIndex]);logo.width+=delta;clampLogo(logo)},'logo-change')}
function handlePointerDown(e){if(editing)return;const el=e.target.closest?.('#studio-canvas [data-studio-element-id]');if(!el)return;selectElement(el);const id=el.dataset.studioElementId,override=getElementOverride(getActiveSlide(),id),zoom=Math.max(.1,Number(store.project.ui?.zoomValue)||1),canvasRect=$('#studio-canvas').getBoundingClientRect(),rect=el.getBoundingClientRect(),logoResize=e.target.closest('[data-logo-resize]'),elementResize=e.target.closest('[data-element-resize]');elementGesture={type:logoResize?'logo-width':elementResize?'scale':'move',id,el,pointerId:e.pointerId,startX:e.clientX,startY:e.clientY,startOverride:override,startScale:Number(override.scale)||1,startLogo:{...getSlideLogo()},zoom,moved:false,startCenter:{x:(rect.left-canvasRect.left+rect.width/2)/zoom,y:(rect.top-canvasRect.top+rect.height/2)/zoom},canvasSize:{width:canvasRect.width/zoom,height:canvasRect.height/zoom},bounds:{minX:-(rect.left-canvasRect.left)/zoom,maxX:(canvasRect.right-rect.right)/zoom,minY:-(rect.top-canvasRect.top)/zoom,maxY:(canvasRect.bottom-rect.bottom)/zoom}};el.setPointerCapture?.(e.pointerId);if(logoResize||elementResize)e.preventDefault()}
function snapElementMove(g,moveX,moveY){const targetX=g.canvasSize.width/2,targetY=g.canvasSize.height/2,deltaX=targetX-(g.startCenter.x+moveX),deltaY=targetY-(g.startCenter.y+moveY),snapX=Math.abs(deltaX)<=ALIGNMENT_SNAP_DISTANCE,snapY=Math.abs(deltaY)<=ALIGNMENT_SNAP_DISTANCE;if(snapX)moveX+=deltaX;if(snapY)moveY+=deltaY;showAlignmentGuides({x:snapX,y:snapY,label:snapX&&snapY?'Centré horizontalement et verticalement':snapX?'Centré horizontalement':'Centré verticalement'});return {moveX,moveY}}
function handlePointerMove(e){if(!elementGesture||elementGesture.pointerId!==e.pointerId)return;const g=elementGesture,dx=(e.clientX-g.startX)/g.zoom,dy=(e.clientY-g.startY)/g.zoom;if(Math.hypot(dx,dy)<2&&!g.moved)return;g.moved=true;e.preventDefault();if(g.type==='logo-width'){const logo={...g.startLogo,width:g.startLogo.width+dx};clampLogo(logo);g.finalLogo=logo;updateLogoPreview(logo);return}if(g.type==='scale'){const next=Math.max(.2,Math.min(4,g.startScale+(dx+dy)/240));g.finalOverride={...g.startOverride,scale:next};applyElementOverride(g.el,g.finalOverride);const output=$('[data-element-prop="scale"]')?.closest('label')?.querySelector('output');if(output)output.textContent=elementOutput('scale',next);return}let moveX=Math.max(g.bounds.minX,Math.min(g.bounds.maxX,dx)),moveY=Math.max(g.bounds.minY,Math.min(g.bounds.maxY,dy));({moveX,moveY}=snapElementMove(g,moveX,moveY));g.finalOverride={...g.startOverride,x:(Number(g.startOverride.x)||0)+moveX,y:(Number(g.startOverride.y)||0)+moveY};applyElementOverride(g.el,g.finalOverride)}
function handlePointerUp(e){if(!elementGesture||e?.pointerId!==undefined&&elementGesture.pointerId!==e.pointerId)return;const g=elementGesture;elementGesture=null;hideAlignmentGuides();if(!g.moved)return;if(g.type==='logo-width'){const finalLogo=g.finalLogo||g.startLogo;store.commit('Logo redimensionné',p=>Object.assign(getSlideLogo(p.slides[p.activeSlideIndex]),finalLogo),'logo-change');showToast(`Logo ajusté à ${Math.round(finalLogo.width)} px`,'success');return}const finalOverride=g.finalOverride||g.startOverride;store.commit(g.type==='scale'?'Élément redimensionné':'Élément déplacé',p=>setElementOverride(p.slides[p.activeSlideIndex],g.id,finalOverride),'element-change')}

function clampZoom(percent){return Math.max(ZOOM_MIN,Math.min(ZOOM_MAX,Math.round(Number(percent)/ZOOM_STEP)*ZOOM_STEP))}
function getFitZoomScale(){const p=store.project,shell=$('#canvasShell');if(!shell)return .75;return Math.max(ZOOM_MIN/100,Math.min(ZOOM_MAX/100,(shell.clientWidth-64)/p.format.width,(shell.clientHeight-64)/p.format.height))}
function setZoomPercent(percent){store.project.ui=store.project.ui||{};store.project.ui.zoomMode='custom';store.project.ui.zoomValue=clampZoom(percent)/100;applyZoom()}
function setZoomFit(){store.project.ui=store.project.ui||{};store.project.ui.zoomMode='fit';applyZoom()}
function stepZoom(direction){const current=Math.round((Number(store.project.ui?.zoomValue)||getFitZoomScale())*100);setZoomPercent(current+direction*ZOOM_STEP)}
function applyZoom(){const p=store.project,ui=p.ui||(p.ui={});const scale=ui.zoomMode==='custom'?Math.max(ZOOM_MIN/100,Math.min(ZOOM_MAX/100,Number(ui.zoomValue)||.75)):getFitZoomScale();ui.zoomValue=scale;const percent=Math.round(scale*100);const range=$('#zoomRange'),value=$('#zoomValue'),fit=$('#zoomFitButton'),canvas=$('#studio-canvas'),frame=$('#canvasZoomFrame');if(range)range.value=String(clampZoom(percent));if(value)value.textContent=`${percent} %`;if(fit){fit.classList.toggle('is-active',ui.zoomMode!=='custom');fit.setAttribute('aria-pressed',String(ui.zoomMode!=='custom'))}if(frame){frame.style.width=`${Math.ceil(p.format.width*scale)}px`;frame.style.height=`${Math.ceil(p.format.height*scale)}px`}if(canvas)canvas.style.transform=`scale(${scale})`}
function previewInspectorProperty(input){const id=store.project.ui?.selectedElementId;if(!id)return;const prop=input.dataset.elementProp,value=normalizedElementProperty(prop,input.value);previewElementOverride($('#studio-canvas'),id,{[prop]:value});const output=input.closest('label')?.querySelector('output');if(output)output.textContent=elementOutput(prop,value)}
function commitInspectorProperty(input){const id=store.project.ui?.selectedElementId;if(!id)return;const prop=input.dataset.elementProp,value=normalizedElementProperty(prop,input.value);store.commit('Propriété de l’élément modifiée',p=>setElementOverride(p.slides[p.activeSlideIndex],id,{[prop]:value}),'element-change')}
function setSelectedLayer(front=true){const id=store.project.ui?.selectedElementId;if(!id)return;store.commit(front?'Élément placé au premier plan':'Élément placé à l’arrière-plan',p=>setElementOverride(p.slides[p.activeSlideIndex],id,{zIndex:front?50:0}),'element-change')}
function resetSelectedElement(){const id=store.project.ui?.selectedElementId;if(!id)return;store.commit('Réglages de l’élément réinitialisés',p=>resetElementOverride(p.slides[p.activeSlideIndex],id),'element-change');showToast('Élément remis à sa position et sa taille d’origine','success')}
function nudgeSelectedElement(dx,dy){const id=store.project.ui?.selectedElementId;if(!id||!selectedCanvasElement(id))return;store.commit('Élément déplacé au clavier',p=>{const slide=p.slides[p.activeSlideIndex],current=getElementOverride(slide,id);setElementOverride(slide,id,{x:(Number(current.x)||0)+dx,y:(Number(current.y)||0)+dy})},'element-change')}
async function handleClick(e){const socialAction=e.target.closest?.('[data-action]')?.dataset.action;if(socialAction==='previewFacebook'){await previewFacebookCover();return}if(socialAction==='moreModels'){state.galleryLimit+=24;renderLeft();return}if(socialAction==='publicationData'){openStudioSidebarPanel('data');return}if(socialAction==='copyPublication'){await copyPublication();return}if(socialAction==='resetPublication'){store.commit('Texte de publication actualisé',p=>{if(p.publications)delete p.publications[publicationKey(getActiveTemplate(),state.publicationNetwork)]});return}if(socialAction==='exportCarousel'){await doCarouselExport();return}const a=e.target.closest?.('[data-action]')?.dataset.action;const model=e.target.closest?.('[data-template-id]');if(model&&!model.closest('#studio-canvas'))setTemplate(model.dataset.templateId);const slideButton=e.target.closest?.('[data-slide]');if(slideButton)store.setSlide(Number(slideButton.dataset.slide));const canvasElement=e.target.closest?.('#studio-canvas [data-studio-element-id]');if(canvasElement)selectElement(canvasElement);if(a==='copySeasonalCaption'){const field=document.getElementById(e.target.closest('[data-caption-target]').dataset.captionTarget);try{await navigator.clipboard.writeText(field.value);showToast('Texte de publication copié','success')}catch{field.focus();field.select();showToast('Texte sélectionné : utilisez Copier.','info')}}if(a==='differentComposition')chooseDifferentComposition();if(a==='zoomOut')stepZoom(-1);if(a==='zoomIn')stepZoom(1);if(a==='zoomFit')setZoomFit();if(a==='autoFix'){autoFixActiveSlide()}if(a==='openExport'){renderMotionControls();$('#exportCarouselButton').hidden=store.project.slides.length<2;$('#exportDialog').showModal()}if(a==='toggleMotion'){motionController?.setPlaying(!motionController.playing);renderMotionControls()}if(a==='exportMotion')await doMotionExport();if(a==='closeExport')$('#exportDialog').close();if(a==='exportStandard')await doExport(1);if(a==='exportHd')await doExport(2);if(a==='save')await saveStudioProject();if(a==='undo')store.undo();if(a==='redo')store.redo();if(a==='addSlide'){showFilmstrip(true);store.commit('Slide ajoutée',p=>{p.slides.push(normalizeSlide({formation:p.formation,templateId:getActiveSlide().templateId}));p.activeSlideIndex=p.slides.length-1})}if(a==='logoOfficial')store.commit('Logo officiel restauré',p=>{p.branding.logoUrl=window.STUDIO_BOOTSTRAP.officialLogoUrl;p.branding.logoName='Logo officiel Intégrale Academy';p.branding.logoVisible=true},'logo-change');if(a==='logoDelete')store.commit('Logo masqué',p=>{p.branding.logoVisible=false});if(a==='logoSmaller')changeLogoSize(-10,'Logo réduit');if(a==='logoLarger')changeLogoSize(10,'Logo agrandi');if(a==='logoReset')store.commit('Taille idéale du logo restaurée',p=>Object.assign(getSlideLogo(p.slides[p.activeSlideIndex]),DEFAULT_LOGO_SETTINGS,p.format.id==='linkedin_cover'?{width:220}:p.format.id==='facebook_cover'?{width:240}:{}),'logo-change');if(a==='logoFit')store.commit('Logo mis en avant',p=>Object.assign(getSlideLogo(p.slides[p.activeSlideIndex]),{width:240,opacity:1}),'logo-change');if(a==='elementBackward')setSelectedLayer(false);if(a==='elementForward')setSelectedLayer(true);if(a==='elementReset')resetSelectedElement();const iconButton=e.target.closest?.('[data-add-icon]');if(iconButton){store.commit('Pictogramme ajouté',p=>{const slide=p.slides[p.activeSlideIndex];slide.elements=slide.elements||[];slide.elements.push({id:crypto.randomUUID(),type:'icon',label:iconButton.dataset.addIcon,x:120+slide.elements.length*28,y:120+slide.elements.length*28})});showToast('Pictogramme ajouté','success')}if(e.target.dataset.ai){try{const j=await studioFetch('/api/admin/social-visuals/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({topic:$('#aiTopic')?.value||'',action:e.target.dataset.ai,project:store.project})});const clean=sanitizeAiPayload(j.content||j);store.commit('Contenu IA généré',p=>{p.name=clean.projectTitle;p.formation=clean.formation;Object.assign(p.slides[p.activeSlideIndex].content,clean.content)});showToast('Contenu IA généré','success')}catch(err){showToast(`IA impossible : ${err.message}`,'error')}}}
function handleInput(e){if(e.target.id==='templateSearch'){state.searchQuery=e.target.value;state.modelFilter='all';state.galleryLimit=24;clearTimeout(state.searchTimer);state.searchTimer=setTimeout(()=>{refreshTemplateOptions();renderLeft()},140);return}if(e.target.dataset.elementProp)previewInspectorProperty(e.target);if(e.target.dataset.logoProp){const logo={...getSlideLogo(),[e.target.dataset.logoProp]:Number(e.target.value)};clampLogo(logo);updateLogoPreview(logo)}if(e.target.id==='zoomRange')setZoomPercent(e.target.value);if(e.target.id==='projectName')store.project.name=e.target.value}
function handleChange(e){if(e.target.id==='studioUsageFilter'){state.usageFilter=e.target.value;state.galleryLimit=24;renderLeft();return}if(e.target.id==='templateUsed'){saveTemplateUsage(e.target.checked);return}if(e.target.id==='publicationNetwork'){state.publicationNetwork=e.target.value;renderPublication();return}if(e.target.id==='publicationText'){const key=publicationKey(getActiveTemplate(),state.publicationNetwork),value=e.target.value;store.commit('Texte de publication modifié',p=>{p.publications=p.publications||{};p.publications[key]=value});return}if(e.target.id==='studioModelFilter'){state.modelFilter=e.target.value;state.galleryLimit=24;renderLeft();return;}if(e.target.dataset.content)setContentValue(e.target.dataset.content,e.target.value);if(e.target.dataset.elementProp)commitInspectorProperty(e.target);if(e.target.dataset.logoProp)store.commit('Logo modifié',p=>{const logo=getSlideLogo(p.slides[p.activeSlideIndex]);logo[e.target.dataset.logoProp]=Number(e.target.value);clampLogo(logo)},'logo-change');if(e.target.dataset.elementText){const id=store.project.ui?.selectedElementId,key=e.target.dataset.elementContentKey,value=e.target.value;if(key)setContentValue(key,value,'Texte modifié');else if(id)store.commit('Texte modifié',p=>setElementOverride(p.slides[p.activeSlideIndex],id,{text:value}),'element-change')}if(e.target.id==='inspectorFormation'||e.target.id==='brandFormation')setFormation(e.target.value);if(e.target.id==='inspectorTemplate')setTemplate(e.target.value);if(e.target.id==='formatSelect')store.commit('Format changé',p=>p.format=FORMATS[e.target.value]);if(e.target.id==='showLogo')store.commit('Logo affiché/masqué',p=>p.branding.logoVisible=e.target.checked);if(e.target.id==='showSafe')store.commit('Marges affichées/masquées',p=>p.slides[p.activeSlideIndex].options.showSafeMargins=e.target.checked);if(e.target.id==='logoInput'&&e.target.files?.[0])importLogo(e.target.files[0]).catch(err=>showToast(`Import impossible : ${err.message}`,'error'))}
function handleStudioEnhancementClick(e){const emojiButton=e.target.closest?.('[data-add-emoji]'),promptButton=e.target.closest?.('[data-ai-design-prompt]'),action=e.target.closest?.('[data-action]')?.dataset.action;if(emojiButton){const glyph=emojiButton.dataset.addEmoji;store.commit('Emoji ajouté',p=>{const slide=p.slides[p.activeSlideIndex],count=(slide.elements||[]).length;slide.elements=slide.elements||[];slide.elements.push({id:crypto.randomUUID(),type:'emoji',glyph,label:`Emoji ${glyph}`,x:130+(count%5)*34,y:160+(count%4)*42,fontSize:72})},'element-add');showToast(`${glyph} ajouté au template`,'success')}if(promptButton){const input=$('#aiDesignPrompt');if(input){input.value=promptButton.dataset.aiDesignPrompt;input.focus()}}if(action==='applyAiDesign')applyAiDesignPrompt();if(action==='resetAiDesign')resetAiDesign()}
function handleStudioEnhancementChange(e){if(e.target.id==='visualInput'&&e.target.files?.[0])importVisual(e.target.files[0]).catch(err=>showToast(`Import impossible : ${err.message}`,'error'))}
function handleKeydown(e){if(editing){if(e.key==='Escape'){e.preventDefault();cancelInlineTextEdit()}if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();commitInlineTextEdit(editing.el)}return}if(e.key==='Enter'&&document.activeElement?.dataset?.studioTextEditable==='true'){startInlineTextEdit(document.activeElement);return}const formControl=e.target.closest?.('input,textarea,select,[contenteditable]');if(formControl||e.ctrlKey||e.metaKey||e.altKey)return;const amount=e.shiftKey?10:1;if(e.key==='ArrowLeft'){e.preventDefault();nudgeSelectedElement(-amount,0)}if(e.key==='ArrowRight'){e.preventDefault();nudgeSelectedElement(amount,0)}if(e.key==='ArrowUp'){e.preventDefault();nudgeSelectedElement(0,-amount)}if(e.key==='ArrowDown'){e.preventDefault();nudgeSelectedElement(0,amount)}if(e.key==='+'||e.key==='='){e.preventDefault();stepZoom(1)}if(e.key==='-'){e.preventDefault();stepZoom(-1)}if(e.key==='0'){e.preventDefault();setZoomFit()}}
document.addEventListener('click',handleStudioEnhancementClick);document.addEventListener('change',handleStudioEnhancementChange);document.addEventListener('dblclick',e=>{const element=e.target.closest?.('#studio-canvas [data-studio-element-id]');if(element?.dataset.studioTextEditable==='true')startInlineTextEdit(element)});document.addEventListener('focusout',e=>{if(editing?.el===e.target)commitInlineTextEdit(e.target)});document.addEventListener('paste',e=>{if(editing){e.preventDefault();document.execCommand('insertText',false,(e.clipboardData||window.clipboardData).getData('text'))}});
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}

function showFilmstrip(show){
  const strip=$('#filmstrip'),toggle=$('#studioSlidesToggle');strip.hidden=!show;toggle.setAttribute('aria-expanded',String(show));
  try{localStorage.setItem('studio.filmstripOpen',String(show))}catch(_error){}
  applyZoom();
}
function bindFilmstrip(){
  let show=false;try{show=localStorage.getItem('studio.filmstripOpen')==='true'}catch(_error){}
  showFilmstrip(show);$('#studioSlidesToggle').addEventListener('click',()=>showFilmstrip($('#filmstrip').hidden));
}
function renderMotionControls(){
  const available=Boolean(motionController?.available),playing=Boolean(motionController?.playing);
  const toggle=$('#studioMotionToggle');toggle.hidden=!available;toggle.textContent=playing?'Ⅱ Animation':'▶ Animation';toggle.setAttribute('aria-pressed',String(playing));toggle.setAttribute('aria-label',playing?'Mettre l’animation en pause':'Lire l’animation');
  $('#exportMotionButton').hidden=!available;
}
function fitTemplatePreviews(){for(const preview of $$('.studio-new2-preview')){const width=preview.clientWidth;const actualWidth=parseFloat(preview.firstElementChild?.style.width)||1080,actualHeight=parseFloat(preview.firstElementChild?.style.height)||1080;preview.style.height=width*actualHeight/actualWidth+'px';if(preview.firstElementChild){preview.firstElementChild.style.transform=`scale(${width/actualWidth})`;fitSlide(preview.firstElementChild,{waitForPaint:false}).catch(error=>console.warn('[STUDIO] Aperçu non ajusté',error))}}}
async function doMotionExport(){
  if(store.project.ui?.isExporting)return;store.project.ui.isExporting=true;
  const buttons=$$('[data-action="exportStandard"],[data-action="exportHd"],[data-action="exportMotion"],[data-action="exportCarousel"],[data-action="closeExport"]');
  const resume=motionController?.playing;motionController?.setPlaying(false);renderMotionControls();
  try{
    buttons.forEach(button=>button.disabled=true);
    const result=await exporter.exportMotion({project:store.project,slide:getActiveSlide(),onStatus:message=>$('#exportMessage').textContent=message,onProgress:percent=>$('#exportProgress').value=percent});
    const url=URL.createObjectURL(result.blob),a=document.createElement('a');a.href=url;a.download=($('#exportFilename').value||'studio-visuel')+'-anime.'+result.extension;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);
    $('#exportMessage').textContent=`Vidéo ${result.extension.toUpperCase()} terminée : ${result.width} × ${result.height} · ${result.duration} s`;
    showToast('Vidéo prête à publier','success');
  }catch(error){$('#exportMessage').textContent=`Export impossible : ${error.message}`;showToast(error.message,'error')}
  finally{buttons.forEach(button=>button.disabled=false);store.project.ui.isExporting=false;motionController?.setPlaying(resume);renderMotionControls()}
}

function autoFixActiveSlide(){
  const errors=runValidation().blockingErrors;
  const ids=[...new Set(errors.flatMap(({element})=>[element?.dataset.studioElementId,...[...(element?.querySelectorAll?.('[data-studio-element-id]')||[])].map(node=>node.dataset.studioElementId)]).filter(Boolean))];
  store.commit('Ajustement des éléments en dépassement',p=>{const slide=p.slides[p.activeSlideIndex];for(const id of ids){const override=getElementOverride(slide,id);const kept={};for(const key of ['text','opacity','zIndex'])if(override[key]!==undefined)kept[key]=override[key];resetElementOverride(slide,id);if(Object.keys(kept).length)setElementOverride(slide,id,kept)}},'layout-fix');
  showToast('Positions et tailles recalculées ; vos textes sont conservés.','success');
}

function refreshTemplateOptions(){
 const current=getActiveSlide().templateId,items=readyTemplates().filter(t=>matchesTemplateSearch(t,state.searchQuery));
 const active=state.templateRegistry[current];if(active&&!items.some(t=>t.id===current))items.unshift(active);
 optionize($('#inspectorTemplate'),items,t=>t.id,t=>`${state.used[t.id]?'✅ ':''}${t.name}`);$('#inspectorTemplate').value=current;
}
function renderPublication(){const panel=$('#publicationPanel');if(!panel)return;const template=getActiveTemplate(),key=publicationKey(template,state.publicationNetwork),expected=store.project.publications?.[key]??publicationText(store.project,template,state.publicationNetwork);if(panel.dataset.publicationKey===key&&$('#publicationText')?.value===expected)return;panel.dataset.publicationKey=key;panel.innerHTML=renderPublicationPanel(store.project,template,state.publicationNetwork)}
async function copyPublication(){
 const field=$('#publicationText');if(!field)return;
 try{await navigator.clipboard.writeText(field.value);showToast('Texte complet copié, avec emojis et hashtags','success')}
 catch{field.focus();field.select();showToast('Texte sélectionné : utilisez Ctrl+C ou Copier.','info')}
}
async function loadTemplateUsage(){
 try{
  const data=cfg.demo?{used:JSON.parse(localStorage.getItem('studio.qa.templateUsage')||'{}')}:await studioFetch('/api/admin/studio/template-usage',{signal:AbortSignal.timeout(10000)});
  if(!data.used||typeof data.used!=='object')throw new Error('Reconnectez-vous pour charger le suivi.');
  state.used=data.used;state.usageLoaded=true;state.usageError='';
 }catch(error){state.usageLoaded=false;state.usageError=error.message;showToast('Le suivi d’utilisation n’a pas pu être chargé. Vous pouvez réessayer.','error')}
 refreshUsageControls();
}
function refreshUsageControls(){
 const checkbox=$('#templateUsed');if(!checkbox)return;checkbox.checked=Boolean(state.used[getActiveSlide().templateId]);checkbox.disabled=!state.usageLoaded||state.usageSaving;
 $('#templateUsageStatus').innerHTML=state.usageSaving?'Enregistrement du suivi…':state.usageLoaded?(checkbox.checked?'✅ Déjà utilisé · suivi enregistré':'Suivi conservé pour votre compte.'):'Suivi indisponible. <button type="button" data-action="retryUsage">Réessayer</button>';
 for(const badge of $$('[data-used-id]'))badge.hidden=!state.used[badge.dataset.usedId];
}
async function saveTemplateUsage(used){
 if(!state.usageLoaded||state.usageSaving)return;
 const templateId=getActiveSlide().templateId,previous={...state.used};state.usageSaving=true;
 if(used)state.used[templateId]=new Date().toISOString();else delete state.used[templateId];refreshUsageControls();refreshTemplateOptions();
 try{
  if(cfg.demo)localStorage.setItem('studio.qa.templateUsage',JSON.stringify(state.used));
  else{const result=await studioFetch('/api/admin/studio/template-usage',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({templateId,used}),signal:AbortSignal.timeout(10000)});if(!result.ok||!result.used)throw new Error('Le suivi n’a pas été enregistré.');state.used=result.used;}
  showToast(used?'Template marqué comme déjà utilisé':'Template marqué comme non utilisé','success');
 }catch(error){state.used=previous;showToast(`Suivi non enregistré : ${error.message}`,'error')}
 finally{state.usageSaving=false;refreshUsageControls();refreshTemplateOptions();if(state.usageFilter&&state.usageFilter!=='all')renderLeft()}
}
document.addEventListener('click',async event=>{if(event.target.closest('[data-action="retryUsage"]')){await loadTemplateUsage();refreshTemplateOptions();renderLeft()}});

async function doCarouselExport(){
 if(store.project.ui?.isExporting)return;store.project.ui.isExporting=true;
 const project=structuredClone(store.project),files=[],buttons=$$('#exportDialog button');
 try{
  buttons.forEach(button=>button.disabled=true);
  for(const [index,slide] of project.slides.entries()){
   const template=state.templateRegistry[slide.templateId];if(!template.supportedFormats.includes(project.format.id))throw new Error('Les diapositives doivent partager un format compatible.');
   const data=await exporter.exportSlide({project,slide,outputWidth:project.format.width,outputHeight:project.format.height,onStatus:message=>$('#exportMessage').textContent=`Diapositive ${index+1} sur ${project.slides.length} · ${message}`});
   const bytes=Uint8Array.from(atob(data.split(',')[1]),c=>c.charCodeAt(0));files.push({name:`${String(index+1).padStart(2,'0')}-integrale-academy.png`,bytes});$('#exportProgress').value=(index+1)/project.slides.length*100;
  }
  files.push({name:'texte-publication.txt',bytes:new TextEncoder().encode($('#publicationText')?.value||publicationText(project,getActiveTemplate(),state.publicationNetwork))});
  const blob=createCarouselZip(files),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=($('#exportFilename').value||'integrale-academy')+'-carrousel.zip';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);
  $('#exportMessage').textContent=`Carrousel exporté : ${project.slides.length} images et le texte de publication.`;showToast('Carrousel complet prêt à publier','success');
 }catch(error){$('#exportMessage').textContent=`Export impossible : ${error.message}`;showToast(error.message,'error')}
 finally{buttons.forEach(button=>button.disabled=false);store.project.ui.isExporting=false}
}
